render_chart <- function(data, cfg, manifest) { nums <- data[vapply(data, is.numeric, logical(1))]; if (ncol(nums) < 2) stop("相关性矩阵至少需要两列数值列"); m <- cor(nums, use = "pairwise.complete.obs"); grid <- expand.grid(row = rownames(m), col = colnames(m), stringsAsFactors = FALSE); grid$value <- as.vector(m); palette <- chart_palette(cfg, 9); p <- ggplot2::ggplot(grid, ggplot2::aes(x = col, y = row, fill = value)) + ggplot2::geom_tile(linewidth = chart_layer_number(cfg, "gridLineWidth", 0.25, 0, 2), colour = "white") + ggplot2::scale_fill_gradient2(limits = c(-1, 1), low = palette[[1]], mid = "white", high = chart_primary(cfg)) + ggplot2::coord_equal() + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(axis.title = ggplot2::element_blank()) + ggplot2::labs(title = cfg$title %||% NULL, fill = "相关系数"); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
